package com.craftworld.game.vehicle;
public final class Aircraft extends Vehicle {public enum Type{SMALL_PLANE,JET,HELICOPTER,BIPLANE} public float pitch,yaw,roll,altitude; public final Type type;public Aircraft(Type t){type=t;}public void update(float throttle,float steering,float dt){if(fuel<=0)return;speed+=(throttle*35-speed*.25f)*dt;y+=Math.sin(pitch)*speed*dt;x+=Math.sin(yaw)*speed*dt;z-=Math.cos(yaw)*speed*dt;yaw+=steering*dt;altitude=y;fuel=Math.max(0,fuel-throttle*dt*.15f);}public void controls(float p,float r,float rudder){pitch=Math.max(-.7f,Math.min(.7f,p));roll=r;yaw+=rudder*.02f;}}
